<?php
require __DIR__.'/includes/app.php'; require_login(); $status=(string)($_GET['status']??'all'); $allowed=['all','pending','success','cancelled','expired']; if(!in_array($status,$allowed,true)) $status='all';
$rows=array_reverse($_SESSION['transactions']); if($status!=='all') $rows=array_filter($rows,function($t) use($status){return $t['status']===$status;});
page_start('Riwayat','riwayat','Semua catatan deposit, lengkap dengan status pembayarannya.');
?><div class="history-summary"><div><span class="muted">Total tabungan berhasil</span><strong><?=rp(saved())?></strong></div><a class="btn primary" href="deposit.php"><?=icon('plus')?>Deposit baru</a></div><section class="panel"><div class="section-title"><h2>Transaksi tabungan</h2><span class="muted"><?=count($rows)?> transaksi</span></div><nav class="filter-tabs" aria-label="Filter status"><?php foreach(['all'=>'Semua','pending'=>'Menunggu','success'=>'Berhasil','cancelled'=>'Dibatalkan','expired'=>'Kedaluwarsa'] as $s=>$label): ?><a class="<?=$status===$s?'selected':''?>" href="riwayat.php?status=<?=$s?>" <?=$status===$s?'aria-current="page"':''?>><?=$label?></a><?php endforeach ?></nav><?php if(!$rows): empty_state('Belum ada transaksi pada kategori ini','Deposit yang Anda buat akan otomatis tersimpan di riwayat.','deposit.php','Buat deposit'); else: ?><div class="table-scroll"><table><thead><tr><th>Tanggal / tujuan</th><th>Nominal</th><th>Kode</th><th>Total</th><th>Status</th><th>Detail</th></tr></thead><tbody><?php foreach($rows as $t): ?><tr><td><strong><?=e(goal_name($t['goal_id']))?></strong><small><?=date('d/m/Y H:i',$t['created'])?> WIB</small></td><td><?=rp($t['amount'])?></td><td>+<?=str_pad((string)$t['code'],3,'0',STR_PAD_LEFT)?></td><td><strong><?=rp($t['total'])?></strong></td><td><?=badge($t['status'])?></td><td><a class="table-link" href="pembayaran.php?id=<?=e($t['id'])?>">Buka<span class="sr-only"> transaksi <?=e($t['id'])?></span></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?><p class="small muted">Hanya transaksi berhasil yang menambah saldo. Total sudah termasuk kode acak.</p></section><?php page_end(); ?>
